options.styles:
.tuiles { display: flex; flex-wrap: wrap; gap: 16px; padding: 8px; }
.tuile { display: flex; flex-direction: column; align-items: center; width: 170px; padding: 14px 8px;
         border: 2px solid #666; border-radius: 10px; text-decoration: none; color: inherit; }
.tuile:hover { background: rgba(128,128,128,.15); }
.tuile img { width: 96px; height: 96px; object-fit: contain; }
.tuile .nom { margin-top: 8px; font-size: 1.2em; font-weight: 600; }
.tuile .detail { font-size: .8em; opacity: .8; }
.tuile.soleil { border-color: #3cb371; } .tuile.nuage { border-color: #f5a623; }
.tuile.orage { border-color: #e03b3b; } .tuile.inconnu { border-color: #8e6bbf; }
